// Synthetic, nonce-only authenticated native protocol. Never runs tools or models.
const fs=require('node:fs'),path=require('node:path');const {WebSocketServer}=require(process.argv[2]);const port=Number(process.argv[3]),tokenPath=process.argv[4],token=fs.readFileSync(tokenPath,'utf8').trim(),home=process.env.CODEX_HOME;
const idPath=path.join(home,'fixture-native-id');if(!fs.existsSync(idPath))fs.writeFileSync(idPath,'fixture-existing-thread',{mode:0o600});
const server=new WebSocketServer({host:'127.0.0.1',port,verifyClient:info=>info.req.headers.authorization===`Bearer ${token}`});
server.on('connection',ws=>ws.on('message',bytes=>{const v=JSON.parse(String(bytes));if(!v.method||v.id===undefined)return;const configuration=JSON.parse(fs.readFileSync(path.join(home,'config'),'utf8'));let result;
if(v.method==='initialize')result={userAgent:`codex ${process.versions.node}`};else if(v.method==='config/read'){const canonical=v=>v&&typeof v==='object'&&!Array.isArray(v)?Object.fromEntries(Object.keys(v).sort().map(k=>[k,canonical(v[k])])):Array.isArray(v)?v.map(canonical):v;const crypto=require('node:crypto'),file=path.join(home,'config'),version='sha256:'+crypto.createHash('sha256').update(JSON.stringify(canonical(configuration))).digest('hex');result={config:configuration,origins:{mcp_servers:{name:{type:'user',file,profile:null},version}},layers:[{name:{type:'user',file,profile:null},version,config:configuration,disabledReason:null}]};}else if(v.method==='mcpServerStatus/list')result={data:Object.keys(configuration.mcp_servers||{}).map(name=>({name,pluginId:null,runtimeStatus:'connected'})),nextCursor:null};else if(v.method==='project/list')result={data:[{id:'fixture-project',roots:[{path:home}]}],nextCursor:null};else if(v.method==='thread/start')result={thread:{id:'fixture-created-thread',cwd:home,projectId:'fixture-project',status:{type:'idle'}}};else if(v.method==='thread/name/set')result={};else if(v.method==='turn/start')result={turn:{id:'fixture-turn'}};else if(v.method==='turn/steer')result={turnId:'fixture-turn'};else if(v.method==='thread/turns/list')result={data:v.params.itemsView==='summary'?[{id:'fixture-turn',status:'inProgress'}]:[],nextCursor:null};else result={thread:{id:v.params.threadId||fs.readFileSync(idPath,'utf8'),cwd:home,status:(configuration.active||v.params.threadId==='fixture-existing-thread')?{type:'active',activeFlags:[]}:{type:'idle'}}};ws.send(JSON.stringify({id:v.id,result}));}));
if(process.argv[5]==='ignore-term')process.on('SIGTERM',()=>{});

if(process.argv[5]==='extra-unix')require('node:net').createServer().listen(path.join(home,'extra-control.sock'));
